package syntax

import "testing"

func TestIsGenerated(t *testing.T) {
	cases := map[string]struct {
		src  string
		want bool
	}{
		"generator header after doc lines": {
			src:  "//! Per-operation response enums.\n//!\n//! Generated by openapi-to-rust v0.16.0.\n#![allow(clippy::large_enum_variant)]\nfn f() {}\n",
			want: true,
		},
		"at-generated marker": {
			src:  "// @generated\nfn f() {}\n",
			want: true,
		},
		"go-style marker in block comment": {
			src:  "/* Code generated by prost. DO NOT EDIT. */\nfn f() {}\n",
			want: true,
		},
		"do not edit after blank line": {
			src:  "\n// Do not edit manually - regenerate using the script.\nfn f() {}\n",
			want: true,
		},
		"prose mentioning generated keys": {
			src:  "//! Keys generated by the TypeScript issuer must be accepted.\nfn f() {}\n",
			want: false,
		},
		"marker only after code": {
			src:  "fn f() {}\n// @generated\n",
			want: false,
		},
		"marker inside a string literal": {
			src:  "//! The generator.\nconst HEADER: &str = \"// Do not edit manually\";\n",
			want: false,
		},
		"plain file": {
			src:  "use std::fmt;\n",
			want: false,
		},
	}
	for name, c := range cases {
		t.Run(name, func(t *testing.T) {
			if got := IsGenerated([]byte(c.src)); got != c.want {
				t.Errorf("IsGenerated = %v, want %v", got, c.want)
			}
		})
	}
}
